from collections import deque

def get_connected_components(color, grid):
    visited = set()
    components = []

    for r in range(10):
        for c in range(10):
            if grid[r][c] == color and (r,c) not in visited:
                # BFS from this pixel
                component = []
                queue = deque([(r,c)])
                visited.add((r,c))

                while queue:
                    cr, cc = queue.popleft()
                    component.append((cr, cc))

                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < 10 and 0 <= nc < 10:
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))
                components.append(component)

    return components

